import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#3
it('reports a wrong type at its property path without the value', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
    async () => 'sunny'
  );
  const response = await registry.execute('weather', {location: 731924});
  expect(response.result).toMatch(/"'^((?!731924).)*'"\\/location.*type.*string/i);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.type-path.test.ts"
